            ? raw.replaceFirst(titleMatch.group(0)!, '').trimLeft()
            : raw;
        final firstPara = RegExp(
          r'^([^\n#|>-][^\n]*(?:\n(?!\n)[^\n#|>-][^\n]*)*)',
          multiLine: true,
        ).firstMatch(body);
        final lede = firstPara != null ? plainText(firstPara.group(1)!) : '';
        return DocsPage(
          source: source,
          title: title,
          body: body,
          description: lede.isNotEmpty ? lede : source.description,
          raw: raw,
        );
      }(),
  ];
}

