      continue;
    }
    final h = _heading.firstMatch(t);
    if (h != null) {
      flushPara();
      final level = h.group(1)!.length;
      out.writeln(
        '<h$level>${renderInline(h.group(2)!, rewriteLink: rewriteLink, rewriteImg: rewriteImg)}</h$level>',
      );
      i++;
      continue;
    }
    if (_hr.hasMatch(t)) {
