  ];
}

List<DocsPage> loadDocs(String root) {
  return [
    for (final source in docsRegistry)
      () {
        final raw = File('$root/${source.source}').readAsStringSync();
        final titleMatch = RegExp(
          r'^#\s+(.+)$',
