      expect(status, 200);
      expect(type, 'text/plain');
      for (final bot in [
        'GPTBot',
        'OAI-SearchBot',
        'ChatGPT-User',
        'Google-Extended',
        'ClaudeBot',
        'anthropic-ai',
        'PerplexityBot',
        'Perplexity-User',
        'CCBot',
        'Applebot-Extended',
        'Meta-ExternalAgent',
      ]) {
        expect(
          body,
          contains('User-agent: $bot\nAllow: /\n'),
          reason: '$bot must be welcomed by name',
        );
      }
      expect(body, contains('User-agent: *\nAllow: /'));
      expect(body, contains('https://fa1.dev/llms.txt'));
      expect(body, contains('https://fa1.dev/llms-full.txt'));
