        lessThan(150 * 1024),
        reason: 'context-window budget (gh-1476 threat model)',
      );
    },
  );
});

group('structured data (gh-1476 D3/D4)', () {
  List<Map<String, dynamic>> jsonLdBlocks(String html) => [
    for (final m in RegExp(
