  test('every page in site/ has only parseable JSON-LD', () {
    final files = Directory('site')
        .listSync(recursive: true)
        .whereType<File>()
        .where((f) => f.path.endsWith('.html'));
    var checked = 0;
    for (final f in files) {
      for (final block in jsonLdBlocks(f.readAsStringSync())) {
        expect(
