List<SitePage> collectPages(List<BlogPost> posts, List<DocsPage> docs) {
  final newestPost = posts.isEmpty ? '' : posts.first.lastmod;
  final blogLastmod = newestPost.compareTo(blogIndexFloor) > 0
      ? newestPost
