    final updated = meta['updated'];
    if (updated != null && updated.isNotEmpty) return updated;
    final date = meta['date'];
    if (date != null && date.isNotEmpty) return date;
    final prefix = RegExp(r'^(\d{4}-\d{2}-\d{2})').firstMatch(slug);
