String buildLlmsFull({
  required String llmsTxt,
  required List<BlogPost> posts,
  required List<DocsPage> docs,
}) {
  final out = StringBuffer()
    ..writeln('# Fa (Flutter Agent Harness) — llms-full.txt')
    ..writeln()
    ..writeln(
