    ..writeln('> Generated by scripts/build_site.dart — do not edit (gh-1476).')
    ..writeln()
    ..writeln('# $siteOrigin/llms.txt')
    ..writeln()
    ..writeln(llmsTxt.trimRight())
    ..writeln()
