    ..writeln();
  for (final p in posts) {
    out
      ..writeln('# ${p.url}')
      ..writeln()
      ..writeln(p.body.trim())
      ..writeln();
  }
  out
    ..writeln('## Documentation (full text)')
    ..writeln();
  for (final d in docs) {
    out
      ..writeln('# ${d.url}')
      ..writeln()
      ..writeln(d.raw.trim())
      ..writeln();
  }
  final text = out.toString();
  if (text.length > llmsFullBudgetBytes) {
    throw StateError(
      'llms-full.txt is ${text.length} bytes — over the '
      '$llmsFullBudgetBytes-byte budget (gh-1476 threat model). Curate '
      'fewer/smaller sources or raise the cap deliberately.',
    );
  }
  return text;
}

