        '${p.author.isNotEmpty ? ' · ${escapeHtml(p.author)}' : ''}</div>',
      )
      ..writeln('<p>${escapeHtml(p.description)}</p>')
      ..writeln('</a>');
  }
  out
    ..writeln('</div>')
    ..write(blogIndexEnd);
  return out.toString();
}

