/// Computes every generated artifact without touching disk.
List<OutputFile> buildSite({required String root}) {
  final posts = loadPosts(root);
  final docs = loadDocs(root);

  // The committed template holds the markers; the rendered index.html is
  // a generated artifact (gitignored, never committed — PR #1479 owner
  // directive), so the template lives at a non-colliding path.
  final blogIndex = File(
    '$root/site/blog/index.template.html',
  ).readAsStringSync();
  final block = blogIndexBlock(posts);
  final startIdx = blogIndex.indexOf(blogIndexStart);
  final endIdx = blogIndex.indexOf(blogIndexEnd);
  if (startIdx < 0 || endIdx < 0 || endIdx < startIdx) {
    throw StateError(
      'site/blog/index.template.html is missing the #blog-post-list '
      'block markers — restore them from git.',
    );
  }
  final regeneratedIndex = blogIndex.replaceRange(
    startIdx,
    endIdx + blogIndexEnd.length,
    block,
  );

  return [
    for (final p in posts)
      OutputFile('site/blog/${p.slug}/index.html', renderBlogPostPage(p)),
    for (final d in docs)
      OutputFile('site/docs/${d.source.slug}/index.html', renderDocsPage(d)),
    OutputFile('site/blog/index.html', regeneratedIndex),
    OutputFile('site/sitemap.xml', buildSitemapXml(collectPages(posts, docs))),
    OutputFile(
      'site/llms-full.txt',
      buildLlmsFull(
        llmsTxt: File('$root/site/llms.txt').readAsStringSync(),
        posts: posts,
        docs: docs,
      ),
    ),
  ];
}

/// Generated page directories (`blog/<slug>`, `docs/<slug>`) directly
/// under [siteDir] — used to prune stale pages after a write and to keep
/// them out of an `--out` static copy.
List<String> _generatedPageDirs(String siteDir) {
  final dirs = <String>[];
  for (final base in ['blog', 'docs']) {
    final dir = Directory('$siteDir/$base');
    if (!dir.existsSync()) continue;
    for (final entity in dir.listSync().whereType<Directory>()) {
      if (File('${entity.path}/index.html').existsSync()) {
        dirs.add(entity.path.substring(siteDir.length + 1));
      }
    }
  }
  return dirs;
}

/// Copies the static (non-generated) site tree from `site/` into [outDir]
/// so an `--out` build yields a complete servable site. Skips the
/// generated artifacts (written from [outputs] instead), any stale
/// generated page dirs left over from an in-tree local build, and
/// `site/app/` (the separately-assembled Flutter web demo, gitignored).
void _copyStaticSite(String root, String outDir) {
  final src = Directory('$root/site');
  final skipDirs = _generatedPageDirs(src.path).toSet();
  bool skip(String rel) =>
      rel == 'app' ||
      rel.startsWith('app/') ||
      skipDirs.any((d) => rel == d || rel.startsWith('$d/'));
  for (final entity in src.listSync(recursive: true)) {
    final rel = entity.path
        .substring(src.path.length + 1)
        .replaceAll('\\', '/');
    if (entity is Directory) {
      if (!skip(rel)) Directory('$outDir/$rel').createSync(recursive: true);
    } else if (entity is File) {
      if (skip(rel)) continue;
      // Generated top-level artifacts are written from [outputs]; the
      // committed blog-index template renders into blog/index.html.
      if (rel == 'sitemap.xml' ||
          rel == 'llms-full.txt' ||
          rel == 'blog/index.template.html') {
        continue;
      }
      final dest = File('$outDir/$rel')..createSync(recursive: true);
      dest.writeAsBytesSync(entity.readAsBytesSync());
    }
  }
}

/// Writes [outputs] (site-relative paths) into the target tree — under
/// `site/` in the repo itself when [outDir] is null (local preview into
/// the gitignored paths), otherwise with [outDir] AS the site root, same
/// layout as `site/` (CI validation / pages.yml deploy). Stale generated
/// page dirs in the target are pruned.
void emitSite({
  required String root,
  String? outDir,
  required List<OutputFile> outputs,
}) {
  // Write target: in-tree the outputs' site-relative paths land under
  // [root]; with `--out`, [outDir] IS the site root (paths lose the
  // leading 'site/'). The prune scan always runs against the siteDir.
  final siteDir = outDir ?? '$root/site';
  String targetPath(OutputFile o) => outDir != null
      ? '$outDir/${o.path.substring('site/'.length)}'
      : '$root/${o.path}';
  if (outDir != null) _copyStaticSite(root, outDir);
  for (final o in outputs) {
    final f = File(targetPath(o))..createSync(recursive: true);
    f.writeAsStringSync(o.content);
  }
  // Prune generated pages whose source disappeared (paths relative to
  // the site root on both sides of the comparison).
  final expectedPaths = {
    for (final o in outputs) o.path.substring('site/'.length),
  };
  for (final dir in _generatedPageDirs(siteDir)) {
    if (!expectedPaths.any((p) => p.startsWith('$dir/'))) {
      Directory('$siteDir/$dir').deleteSync(recursive: true);
      stdout.writeln('pruned stale page: $dir/');
    }
  }
  stdout.writeln(
    'site built: ${outputs.length} artifact(s) — blog posts, docs pages, '
    'sitemap.xml, llms-full.txt${outDir != null ? ' -> $outDir' : ''}',
  );
}

String _repoRoot() {
  var dir = Directory.current;
  while (true) {
    if (Directory('${dir.path}/site').existsSync() &&
        Directory('${dir.path}/scripts').existsSync()) {
      return dir.path;
    }
    final parent = dir.parent;
    if (parent.path == dir.path) {
      stderr.writeln('run from inside the flutter_agent repo');
      exit(1);
    }
    dir = parent;
  }
}

void main(List<String> args) {
  if (args.contains('--check')) {
    stderr.writeln(
      '`--check` was removed (gh-1476 owner directive, PR #1479): '
      'generated artifacts are deploy-time products — gitignored, never '
      'committed — so there is nothing to drift against. Build to a temp '
      'dir and validate the output instead: '
      '`dart scripts/build_site.dart --out <dir>` (+ test/site/* via '
      'FA_SITE_ROOT).',
    );
    exit(2);
  }
  String? outDir;
  final outIdx = args.indexOf('--out');
  if (outIdx >= 0) {
    if (outIdx + 1 >= args.length) {
      stderr.writeln('--out requires a target directory');
      exit(2);
    }
    outDir = args[outIdx + 1];
  }
  final root = _repoRoot();
  emitSite(
    root: root,
    outDir: outDir,
    outputs: buildSite(root: root),
  );
}

